INSERT INTO pull_task_pull_wave (
  task_id, group_execution_id, wave_no, wave_type, wave_status,
  planned_call_count, next_dispatch_at, dispatch_completed_at,
  settled_at, created_at, updated_at
) VALUES (
  #{taskId}, #{groupExecutionId}, #{waveNo}, #{waveType}, #{waveStatus},
  #{plannedCallCount}, #{nextDispatchAt}, #{dispatchCompletedAt},
  #{settledAt}, #{createdAt}, #{updatedAt}
)

