UPDATE pull_task_pull_wave
SET wave_status = #{transition.target.status},
    next_call_seq = #{transition.target.nextCallSeq},
    next_dispatch_at = #{transition.target.nextDispatchAt},
    dispatch_completed_at = #{transition.target.dispatchCompletedAt},
    settled_at = #{transition.target.settledAt},
    version = version + 1,
    updated_at = #{transition.now}
WHERE id = #{transition.scope.id}
  AND group_execution_id = #{transition.scope.groupExecutionId}
  AND wave_status = #{transition.scope.expectedStatus}
  AND version = #{transition.scope.expectedVersion}

UPDATE pull_task_pull_wave
SET wave_status = #{advance.target.waveStatus},
    next_call_seq = #{advance.target.nextCallSeq},
    next_dispatch_at = #{advance.target.nextDispatchAt},
    dispatch_completed_at = #{advance.target.dispatchCompletedAt},
    version = version + 1,
    updated_at = #{advance.now}
WHERE id = #{advance.scope.waveId}
  AND version = #{advance.scope.expectedWaveVersion}
  AND next_call_seq = #{advance.scope.expectedCallSeq}
  AND dispatch_completed_at IS NULL

UPDATE pull_task_pull_wave
SET next_dispatch_at = LEAST(next_dispatch_at, #{now}),
    version = version + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND group_execution_id = #{groupExecutionId}
  AND wave_status = #{expectedStatus}

UPDATE pull_task_pull_wave
SET wave_status = #{targetStatus},
    version = version + 1,
    updated_at = #{now}
WHERE task_id = #{taskId}
  AND wave_status IN
  #{status}

UPDATE pull_task_pull_wave
SET wave_status = #{targetStatus},
    version = version + 1,
    updated_at = #{now}
WHERE group_execution_id = #{groupExecutionId}
  AND wave_status IN
  #{status}
